@dataclass(frozen=True)
class EvidenceDecision:
    """One automatic or reviewed factuality judgment."""

    label: Label
    label_source: str
    detail: str
    evidence_kind: str
    grounding: str
    support_kind: str
    support_span: str | None
    false_spans: tuple[str, ...]
    automatic_label: Label
    human_reviewed: bool = False

    def as_dict(self) -> dict[str, object]:
        return {
            "label": self.label.name,
            "label_source": self.label_source,
            "detail": self.detail,
            "evidence_kind": self.evidence_kind,
            "grounding": self.grounding,
            "support_kind": self.support_kind,
            "support_span": self.support_span,
            "false_spans": list(self.false_spans),
            "automatic_label": self.automatic_label.name,
            "human_reviewed": self.human_reviewed,
        }


@dataclass(frozen=True)
class HumanReview:
    """A review that cites evidence. The file is never invented by training."""

    question_id: str
    label: Label
    reviewer: str
    evidence_note: str


def label_halueval_generation(
    *,
    question: str,
    knowledge: str,
    right_answer: str,
    hallucinated_answer: str,
    answer: str,
) -> EvidenceDecision:
    """Label one generated answer from the passage and the two benchmark claims."""
    if not isinstance(answer, str) or not answer.strip():
        return _decision(
            Label.UNVALIDATED,
            "The generation is empty, so no factual claim was checked.",
            evidence_kind="insufficient",
            grounding="unchecked",
            support_kind="none",
            support_span=None,
            false_spans=(),
        )
    ground = ground_right_answer(knowledge, right_answer)
    false_spans = contradicted_substitutes(
        question=question,
        knowledge=knowledge,
        right_answer=right_answer,
        hallucinated_answer=hallucinated_answer,
    )
    supported = asserts_supported_answer(answer, right_answer) and _asserts_series_markers(
        answer, right_answer
    )
    support_kind = "none"
    support_span = None
    if supported:
        support_kind = "exact" if asserts_phrase(answer, right_answer) else "paraphrase"
        support_span = right_answer.strip()
    false_hits = [span for span in false_spans if asserts_supported_answer(answer, span)]
    if (
        asserts_phrase(answer, hallucinated_answer)
        and not contains_phrase(knowledge, hallucinated_answer)
        and hallucinated_answer.strip() not in false_hits
    ):
        false_hits.append(hallucinated_answer.strip())
    if ground == "ungrounded":
        return _decision(
            Label.UNVALIDATED,
            "The benchmark right answer is not grounded in the knowledge passage. "
            "The generation was not given a binary label.",
            evidence_kind="insufficient",
            grounding=ground,
            support_kind=support_kind,
            support_span=support_span,
            false_spans=tuple(false_hits),
        )
    if supported and false_hits:
        return _decision(
            Label.AMBIGUOUS,
            "The generation asserts the supported answer and a contradicted substitute: "
            + false_hits[0],
            evidence_kind="conflict",
            grounding=ground,
            support_kind=support_kind,
            support_span=support_span,
            false_spans=tuple(false_hits),
        )
    if false_hits:
        return _decision(
            Label.HALLUCINATED,
            "The generation asserts a claim that contradicts the grounded right answer: "
            + false_hits[0],
            evidence_kind="contradiction",
            grounding=ground,
            support_kind="none",
            support_span=None,
            false_spans=tuple(false_hits),
        )
    if supported:
        how = "the right-answer wording" if support_kind == "exact" else "an in-order paraphrase"
        return _decision(
            Label.FAITHFUL,
            f"The generation asserts {how} and no contradicted substitute.",
            evidence_kind="support",
            grounding=ground,
            support_kind=support_kind,
            support_span=support_span,
            false_spans=(),
        )
    return _decision(
        Label.UNVALIDATED,
        "The generation does not assert the supported answer or a contradicted substitute. "
        "A missing reference match was not labeled as a hallucination.",
        evidence_kind="insufficient",
        grounding=ground,
        support_kind="none",
        support_span=None,
        false_spans=(),
    )


def ground_right_answer(knowledge: str, right_answer: str) -> str:
    """Return how the passage supports the benchmark right answer, if it does."""
    if contains_phrase(knowledge, right_answer):
        return "phrase"
    tokens = content_tokens(right_answer)
    if tokens and all(contains_phrase(knowledge, token) for token in tokens):
        return "content_tokens"
    return "ungrounded"


def contradicted_substitutes(
    *,
    question: str,
    knowledge: str,
    right_answer: str,
    hallucinated_answer: str,
) -> tuple[str, ...]:
    """Spans from the benchmark's false answer that conflict with the passage.

    A span is kept only when it is the other side of an explicit ``or`` choice,
    a number or proper name that the passage does not contain, or the whole
    benchmark false sentence when that sentence itself is asserted. A discourse
    word such as ``Both`` is not a substitute. Words that are only missing from
    the right answer are not enough.
    """
    found: list[str] = []
    alternative = or_alternative(question, right_answer)
    if alternative is not None and contains_phrase(hallucinated_answer, alternative):
        found.append(alternative)
    for number in _NUMBER.findall(hallucinated_answer):
        if _blocked_substitute(number, question, knowledge, right_answer):
            continue
        found.append(number)
    for name in _NAME.findall(hallucinated_answer):
        cleaned = name.strip(" .,;:")
        if not cleaned or _overlaps_claim(cleaned, right_answer):
            continue
        if contains_phrase(question, cleaned) or contains_phrase(knowledge, cleaned):
            continue
        if _generic_span(cleaned):
            continue
        found.append(cleaned)
    unique: list[str] = []
    seen: set[str] = set()
    for span in found:
        key = _normalize(span)
        if not key or key in seen or _overlaps_claim(span, right_answer):
            continue
        seen.add(key)
        unique.append(span.strip())
    return tuple(unique)


def or_alternative(question: str, right_answer: str) -> str | None:
    """Return the explicit alternative that is not the grounded right answer."""
    match = _OR.search(question)
    if match is None:
        return None
    left = _edge_name(question[: match.start()], side="left")
    right = _edge_name(question[match.end() :], side="right")
    if left is None or right is None:
        return None
    if _generic_span(left) or _generic_span(right):
        return None
    left_supported = _same_or_contained(left, right_answer)
    right_supported = _same_or_contained(right, right_answer)
    if left_supported and not right_supported:
        return right
    if right_supported and not left_supported:
        return left
    return None


def asserts_supported_answer(answer: str, phrase: str) -> bool:
    """True when ``answer`` asserts ``phrase`` or its content tokens in order."""
    if asserts_phrase(answer, phrase):
        return True
    tokens = content_tokens(phrase)
    if not 1 <= len(tokens) <= 6:
        return False
    normalized = _normalize(answer)
    cursor = 0
    for token in tokens:
        if not asserts_phrase(answer, token):
            return False
        match = re.search(rf"(?<!\w){re.escape(token)}(?!\w)", normalized[cursor:])
        if match is None:
            return False
        cursor += match.end()
    return True


def content_tokens(text: str) -> list[str]:
    """Content tokens used for paraphrase coverage. Stopwords are removed."""
    return [
        token
        for token in _TOKEN.findall(_normalize(text))
        if token not in _STOP and (len(token) >= 2 or token.isdigit())
    ]


def contains_phrase(text: str, phrase: str) -> bool:
    """Word-boundary containment. This does not decide negation."""
    needle = _normalize(phrase)
    if not needle:
        return False
    return re.search(rf"(?<!\w){re.escape(needle)}(?!\w)", _normalize(text)) is not None


def read_human_reviews(path: Path) -> dict[str, HumanReview]:
    """Read a JSONL review file. Rows without an evidence note are refused."""
    reviews: dict[str, HumanReview] = {}
    for line_number, line in enumerate(
        Path(path).read_text(encoding="utf-8").splitlines(), start=1
    ):
        if not line.strip():
            continue
        payload = json.loads(line)
        if not isinstance(payload, dict):
            raise ValueError(f"Review line {line_number} is not an object")
        question_id = payload.get("question_id")
        label_name = payload.get("label")
        reviewer = payload.get("reviewer")
        note = payload.get("evidence_note")
        if not isinstance(question_id, str) or not question_id.strip():
            raise ValueError(f"Review line {line_number} is missing question_id")
        if question_id in reviews:
            raise ValueError(f"Review line {line_number} repeats {question_id}")
        if not isinstance(reviewer, str) or not reviewer.strip():
            raise ValueError(f"Review line {line_number} is missing reviewer")
        if not isinstance(note, str) or len(note.strip()) < 20:
            raise ValueError(
                f"Review line {line_number} needs an evidence_note of at least 20 characters. "
                "Uncertain rows are not converted into ground truth."
            )
        try:
            label = Label[str(label_name)]
        except KeyError as exc:
            raise ValueError(f"Review line {line_number} has an unknown label") from exc
        reviews[question_id] = HumanReview(
            question_id=question_id,
            label=label,
            reviewer=reviewer.strip(),
            evidence_note=note.strip(),
        )
    return reviews


def apply_human_review(decision: EvidenceDecision, review: HumanReview) -> EvidenceDecision:
    """Replace the automatic label with a review that cites evidence."""
    return EvidenceDecision(
        label=review.label,
        label_source=HUMAN_REVIEW_SOURCE,
        detail=f"Human review by {review.reviewer}: {review.evidence_note}",
        evidence_kind=decision.evidence_kind,
        grounding=decision.grounding,
        support_kind=decision.support_kind,
        support_span=decision.support_span,
        false_spans=decision.false_spans,
        automatic_label=decision.automatic_label,
        human_reviewed=True,
    )


def separate_probe_score(
    decision: EvidenceDecision, probe_score: float | None
) -> dict[str, object]:
    """Keep the factuality label independent of a classifier score."""
    return {
        "factuality_label": decision.label.name,
        "label_source": decision.label_source,
        "reference_detail": decision.detail,
        "probe_score": probe_score,
        "probe_score_is_hallucination_probability": False,
        "reference_check_is_separate_from_probe": True,
    }


def binary_training_label(label: Label) -> bool:
    """Ambiguous and unvalidated rows are not supervised binary examples."""
    return label in {Label.FAITHFUL, Label.HALLUCINATED}


def _decision(
    label: Label,
    detail: str,
    *,
    evidence_kind: str,
    grounding: str,
    support_kind: str,
    support_span: str | None,
    false_spans: tuple[str, ...],
) -> EvidenceDecision:
    return EvidenceDecision(
        label=label,
        label_source=GENERATION_LABEL_SOURCE,
        detail=detail,
        evidence_kind=evidence_kind,
        grounding=grounding,
        support_kind=support_kind,
        support_span=support_span,
        false_spans=false_spans,
        automatic_label=label,
        human_reviewed=False,
    )


def _asserts_series_markers(answer: str, right_answer: str) -> bool:
    """A trailing capital letter such as ``National League A`` has to be asserted.

    Dropping that marker would treat a different name as a paraphrase.
    """
    markers = re.findall(r"\b([A-Z])\b", right_answer)
    return all(asserts_phrase(answer, marker) for marker in markers)


def _blocked_substitute(span: str, question: str, knowledge: str, right_answer: str) -> bool:
    return (
        contains_phrase(right_answer, span)
        or contains_phrase(question, span)
        or contains_phrase(knowledge, span)
        or _overlaps_claim(span, right_answer)
    )


def _edge_name(fragment: str, *, side: str) -> str | None:
    names = [match.group(0).strip(" .,;:?") for match in _NAME.finditer(fragment)]
    names = [name for name in names if name and not _generic_span(name)]
    if not names:
        return None
    return names[-1] if side == "left" else names[0]


def _generic_span(span: str) -> bool:
    tokens = content_tokens(span)
    return not tokens or all(token in _GENERIC_SPAN for token in tokens)


def _same_or_contained(left: str, right: str) -> bool:
    return contains_phrase(left, right) or contains_phrase(right, left)


def _overlaps_claim(span: str, right_answer: str) -> bool:
    return _same_or_contained(span, right_answer)


def _normalize(text: str) -> str:
    return _WHITESPACE.sub(" ", text.strip().lower())
